// Comportement des poissons : à quel point c'est agréable à observer, et ce qu'on y voit.
// Échelle : 5 = spectaculaire, 4 = très agréable à observer, 3 = agréable,
// 2 = discret, 1 = très discret. Indexé par slug (voir lib/especes.ts).
// Textes vérifiés espèce par espèce d'après des sources publiques (SeriouslyFish,
// Planet Catfish, Loaches.com, TFH Magazine, Wikipédia, aquariums publics) : ne
// rien ajouter qui ne figure pas dans une source. La note (niveau) est un jugement
// éditorial sur l'intérêt à observer le comportement.
export type Comportement = { niveau: 1 | 2 | 3 | 4 | 5; description: string };

export const COMPORTEMENT_NIVEAUX: Record<number, { libelle: string; phrase: string }> = {
  5: { libelle: 'Spectaculaire', phrase: 'Un comportement à ne pas manquer' },
  4: { libelle: 'Très agréable à observer', phrase: 'Passionnant à regarder' },
  3: { libelle: 'Agréable', phrase: 'Plaisant à observer' },
  2: { libelle: 'Discret', phrase: 'Peu démonstratif' },
  1: { libelle: 'Très discret', phrase: 'Se montre rarement' },
};

const c = (niveau: 1 | 2 | 3 | 4 | 5, description: string): Comportement => ({ niveau, description });

export const COMPORTEMENTS: Record<string, Comportement> = {
  // ── Eau douce : vivipares et petits poissons de banc ──
  'guppy': c(4, "Très actif et sociable, il nage en groupe et ne doit pas rester seul. Le mâle fait la cour en se courbant en S et en vibrant devant la femelle. Plutôt paisible, mais les mâles peuvent mordiller les poissons à longues nageoires."),
  'molly-voile-noir': c(3, "Paisible et actif, il évolue en groupe dans tout le bac. Les mâles poursuivent les femelles avec insistance : prévoir plusieurs femelles par mâle et des zones de plantes denses. Il apprécie un régime riche en végétaux."),
  'platy': c(3, "Très paisible, il s'entend avec la plupart des poissons de communauté et même les mâles se tolèrent entre eux. Les mâles harcèlent parfois les femelles : mieux vaut plusieurs femelles par mâle."),
  'xipho-porte-epee': c(3, "Sociable, il vit en groupe. En espace confiné, les mâles établissent une hiérarchie de dominance et passent beaucoup de temps à défendre leur rang, parfois avec des poursuites."),
  'tetra-neon': c(4, "Paisible, il vit en banc d'au moins 8 à 10 individus et nage de façon synchronisée. Sa bande lumineuse scintille à chaque mouvement : un effet très apprécié en bac planté."),
  'tetra-cardinal': c(4, "Grégaire et paisible, il vit en banc d'au moins six individus. Sa large bande rouge ressort particulièrement dans un bac sombre et planté. Il peut devenir la proie de gros poissons comme les scalaires."),
  'tetra-citron': c(3, "Très paisible, il vit en banc de 8 à 10 individus ou plus. Les mâles se disputent temporairement la place dominante et l'attention des femelles, ce qui rend le groupe plus vivant à regarder."),
  'tetra-rouge-minor': c(3, "Grégaire mais turbulent, il forme des bancs à hiérarchie souple. Il a la réputation de mordiller les nageoires de ses voisins, surtout en petit effectif (12 individus recommandés) : à éviter avec les poissons timides ou à longues nageoires."),
  'tetra-empereur': c(4, "Vif et paisible, c'est l'un des meilleurs tétras de communauté. Il vit en banc d'au moins six individus, idéalement dix ou plus. Les mâles sont territoriaux entre eux, sans conséquence grave dans un bac assez grand, et deviennent plus colorés avec de longues nageoires."),
  'corydoras-de-sterba': c(4, "Paisible et grégaire, il se garde en groupe d'au moins six individus : un banc dans un bac planté est très agréable à regarder. Il fouille le substrat en permanence à la recherche de nourriture, avec des comportements souvent amusants en groupe."),
  'corydoras-bronze': c(4, "Paisible et grégaire, il vit en groupe d'au moins quatre à six individus et fouille le fond sans arrêt. Il peut respirer l'air atmosphérique, ce qui explique ses remontées d'un trait à la surface."),
  'corydoras-panda': c(3, "Petit corydoras paisible qui vit près du fond et fouille le sable. Un peu plus sensible à la qualité de l'eau que les autres corydoras, il est plus agréable à observer en groupe."),
  'corydoras-pygmee': c(4, "Contrairement à la plupart des corydoras, il nage en pleine eau, à mi-hauteur, en bancs serrés. Très paisible, il se sent plus en confiance en groupe d'au moins six, mais il est vite intimidé par de plus gros voisins."),
  'combattant-betta': c(5, "Le mâle, très agressif envers ses congénères, déploie ses nageoires face à un rival ou à son reflet. Il construit un nid de bulles où il recueille les œufs et les garde seul. À garder seul ; il respire l'air en surface et saute : bac couvert."),
  'scalaire': c(4, "Poisson majestueux à la nage lente, généralement pacifique mais chamailleur entre congénères. Un couple pond sur une surface verticale (feuille, ardoise) et les parents gardent œufs et alevins ; les mâles peuvent être territoriaux à cette période, et il peut manger de petits poissons comme les tétras."),
  'discus': c(5, "Poisson de banc très timide, qui a besoin de cachettes et de calme. Les deux parents nourrissent leurs alevins avec le mucus de leur peau, un comportement rare et fascinant à voir."),
  'gourami-nain': c(3, "Timide et territorial, il se calme dans un bac planté, ombragé et riche en cachettes. Les mâles peuvent être très agressifs envers d'autres gouramis et harceler la femelle. Le mâle construit un nid de bulles en surface, et il respire en partie l'air atmosphérique."),
  'gourami-perle': c(4, "L'un des gouramis les plus paisibles, calme et élégant. Les mâles sont territoriaux entre eux. À la reproduction, le mâle construit un nid de bulles sous les plantes flottantes et le garde jusqu'à l'éclosion."),
  'gourami-miel': c(3, "Lent et paisible, il se laisse facilement devancer par des poissons plus vifs : il lui faut des compagnons calmes. En groupe de quatre à six, il forme une hiérarchie, et le mâle prend une livrée orange vive et bleu sombre à la reproduction, avec un nid de bulles."),
  'danio-zebre': c(4, "Grégaire et très actif, il vit en banc d'au moins 8 à 10 individus, moins nerveux en groupe. Il nage en continu et demande un bac assez long. Il peut sauter : mieux vaut couvrir le bac."),
  'danio-leopard': c(4, "Grégaire et très actif, il nage en banc vif et joueur. À garder en groupe d'au moins 8 à 10 individus, comme le danio zébré, et à couvrir pour éviter les sauts."),
  'barbus-de-sumatra': c(4, "Grégaire et turbulent, il forme des hiérarchies en bancs d'au moins 8 à 10 individus, ce qui disperse l'agressivité. Il a la réputation de mordiller les nageoires des autres poissons, surtout en petit nombre : à éviter avec les poissons lents ou à voiles."),
  'barbus-cerise': c(3, "Paisible et timide, il vit en banc. Il peut devenir nerveux avec des poissons plus actifs ; mieux vaut de petits compagnons calmes. Les mâles sont plus petits et plus colorés que les femelles."),
  'barbus-rose': c(3, "Grégaire et généralement paisible, il vit en banc d'au moins 8 à 10 individus. En saison de reproduction, les mâles prennent des couleurs plus vives et se disputent les femelles."),
  'loche-clown': c(5, "Grégaire, elle vit en groupe de six individus ou plus, aime se faufiler dans les interstices et émet des clics audibles. Elle se repose parfois dans des positions inhabituelles, sur le côté, à la verticale ou à plat sur le fond : un comportement naturel qui inquiète souvent à tort."),
  'loche-kuhli': c(2, "Timide et surtout nocturne, elle ne quitte ses cachettes qu'à la tombée de la nuit. Elle vit en groupe d'une douzaine d'individus ou plus et inspecte le gravier grain par grain en poussant le substrat du museau. Des cachettes denses sont indispensables."),
  'ancistrus-plecos-commun': c(3, "Relativement paisible, mais territorial envers ses congénères et les poissons de forme semblable. Les mâles adultes, reconnaissables à leurs tentacules sur la tête, gardent la ponte dans une grotte. Des cachettes suffisantes comptent plus que le décor."),
  'pleco-commun': c(2, "Surtout nocturne : il passe la journée dans un abri (grotte, tube, bois) et sort la nuit brouter algues et restes de nourriture. Il atteint environ 50 cm, devient territorial en grandissant et peut abîmer les plantes : réservé aux très grands bacs."),
  'kribensis': c(4, "Les couples sont monogames et très démonstratifs : la femelle, au ventre pourpre à la ponte, amorce souvent la parade en dansant devant le mâle. Les deux parents guident leurs alevins, les ramènent dans la bouche s'ils s'écartent, et le couple devient très territorial pendant la reproduction."),
  'apistogramma-cacatuoides': c(4, "Paisible en communauté, mais le mâle, aux couleurs plus vives et à la dorsale prolongée, est très territorial : on le garde en couple, trio ou harem. La femelle, jaune pâle qui s'accentue à la ponte, défend sa cavité et soigne seule les œufs."),
  'poisson-arc-en-ciel': c(4, "Très paisible mais rapide, il demande un banc d'au moins 6 à 8 individus, idéalement plus, et reste farouche en petit groupe. Les mâles en pleine forme se font face presque en permanence, et les jeunes mettent plus d'un an à prendre leurs couleurs."),
  'killie-nothobranchius': c(4, "Killi annuel : en aquarium il vit en général 6 à 12 mois, et ses œufs résistent à la sécheresse dans le substrat. Les mâles, plus grands et nettement plus colorés que les femelles, sont l'attraction du bac."),
  'otocinclus': c(3, "Paisible, il vit en groupe d'au moins six et se nourrit d'algues sur les feuilles et les racines. Il est surtout actif la nuit."),
  'rasbora-arlequin': c(3, "Poisson très paisible et grégaire : à garder en groupe de 8 à 10 minimum, il y est moins craintif. À la ponte, il colle ses œufs sous une large feuille ; les adultes les mangent."),
  'rasbora-tete-de-cuivre': c(3, "Vif et paisible, il nage en banc dans la partie haute du bac. Il saute volontiers : couvrir le bac."),
  'poisson-chat-de-verre': c(3, "Paisible mais plutôt timide, il forme des bancs serrés et se sent mieux à six individus au moins. Il supporte mal les voisins plus grands ou turbulents et peut s'en prendre aux œufs ou aux alevins."),
  'poisson-archer': c(5, "Il projette des jets d'eau pour faire tomber les insectes posés sur la végétation au-dessus de la surface : un comportement reproductible en aquarium avec des grillons placés dans la partie plantée. Généralement paisible, il peut manger de petits poissons et se montrer agressif entre congénères ; il atteint 30 cm."),
  'ram-papiliochromis': c(4, "Les adultes vivent en couple, les jeunes en groupe. À la reproduction, chaque couple défend un territoire d'environ 60 cm ; la femelle pond en rangées sur une pierre plate et les deux parents s'occupent des alevins. Sa timidité diminue en présence de petits poissons de banc."),
  'poisson-chat-pictus': c(3, "Prédateur qui avale néons, guppys et autres petits poissons. Seul, il reste caché le jour et sort après l'extinction des lumières ; en groupe de six ou plus, il est plus actif. Ses longs barbillons et son activité gênent les congénères plus lents."),
  'molly-ballon': c(3, "Paisible et actif, il nage en groupe et broute les algues. Les mâles font la cour en dressant la dorsale."),
  'requin-arc-en-ciel': c(2, "De plus en plus territorial en grandissant, il harcèle ses congénères, les poissons de forme proche et souvent les poissons de fond. Il vit probablement en solitaire : à garder seul, avec au moins un mètre de territoire."),
  'requin-a-queue-rouge': c(2, "Souvent caché jeune, il devient de plus en plus territorial et très agressif envers les poissons qui lui ressemblent. À garder seul, ou dans un très grand bac riche en cachettes, et à introduire en dernier."),
  'poisson-lune-metynnis': c(3, "Globalement pacifique, il vit en groupe de cinq au moins dans la partie médiane et haute du bac. Il détruit les plantes, peut manger de très petits poissons et reste nerveux si l'éclairage est vif et les cachettes absentes."),
  'poisson-hachette': c(4, "Il passe presque tout son temps en surface, autour de la végétation flottante, et se sent plus hardi en groupe d'au moins dix. Effrayé, il peut bondir hors de l'eau, d'où le couvercle bien ajusté ; il s'agit d'un saut, pas d'un vol plané, et il saute rarement."),
  'anableps-poisson-a-quatre-yeux': c(5, "Il passe presque tout son temps à la surface et exige un groupe d'au moins six, idéalement une douzaine : seul, il est nerveux. Ses yeux divisés horizontalement voient au-dessus et sous l'eau en même temps. Il bondit puissamment hors de l'eau, couvercle indispensable, et il peut manger de plus petits poissons."),
  'poisson-couteau': c(4, "Nocturne et sensible à la lumière vive, il a besoin de zones sombres pour se cacher le jour. Timide à l'arrivée, il nage aussi bien en avant qu'en arrière et émet un faible champ électrique sans danger pour l'aquariophile. Paisible envers les poissons trop grands pour être mangés, mais territorial envers ses congénères : à garder seul."),
  'poisson-elephant-mormyridae': c(3, "Nocturne, il se replie et s'étiole sous une lumière vive, d'où l'importance des cachettes. Il produit un faible champ électrique pour s'orienter, chasser et communiquer. Il supporte mal ses congénères : à deux, le plus fort harcèle souvent l'autre à mort, il faut en prendre cinq au moins."),
  'raie-d-eau-douce-potamotrygon-motoro': c(3, "Elle reste surtout près du fond mais explore parfois tout le bac. Prédatrice, elle s'attaque à tout poisson plus petit qu'elle ; omnivore, elle mange aussi des plantes aquatiques et s'habitue aux granulés et aliments congelés. Les petits naissent vivants."),
  'arowana-asiatique': c(4, "Prédateur de surface, il se tient dans la partie haute de l'eau, où il prend sa nourriture, et passe pour un sauteur prodigieux : couvercle parfaitement ajusté. Territorial, il vit seul ou en petit nombre et chasse surtout la nuit ; le choix des voisins demande du soin."),
  'esturgeon-nain': c(3, "Poisson de fond très actif qui fouille la vase et le substrat meuble, se nourrit lentement et demande une nourriture qui coule. Solitaire, il peut devenir familier jusqu'à manger à la main. Attention : il convient aux bassins, pas à un aquarium de 20 à 300 L."),

  // ── Bassin ──
  'carpe-koi': c(4, "Une étude montre que des koï recherchent activement le contact avec l'humain : ils mordillent, frottent ou heurtent la main, avec de fortes différences d'un individu à l'autre. Un poisson de bassin attachant, qui vient volontiers à la rencontre de son propriétaire."),
  'poisson-rouge-carassin-dore': c(3, "Très sociable, il aime former un banc, imite ses congénères pour trouver la nourriture et apprend plus vite en observant un autre poisson. Généralement non agressif, il peut se montrer querelleur en cas de manque de nourriture et a besoin d'espace pour s'éloigner des autres."),
  'tanche': c(2, "Surtout active la nuit, elle cherche sa nourriture dans la vase près du fond. Plutôt timide et réservée, elle vit en banc et se garde en groupe de 5 à 10. En été, les mâles poursuivent les femelles à la reproduction."),
  'vairon': c(3, "Poisson de banc : dès les premières semaines de nage libre, les jeunes montrent déjà un comportement de banc, de plus en plus serré avec l'âge. À garder en groupe."),
  'loche-de-bassin': c(3, "Elle se repose une bonne partie de la journée et devient active le soir et la nuit, en circulant dans le substrat jusqu'à ne laisser dépasser que la tête. On dit qu'elle s'agite avant les orages, mais cela repose sur des témoignages d'aquariophiles, pas sur une observation vérifiée. Elle avale de l'air en surface quand l'oxygène manque."),
  'ide-melanote': c(3, "Les jeunes vivent en bancs en eaux claires, les grands adultes en groupes de leur espèce qui suivent des trajets réguliers. L'hiver, il descend en eau profonde, puis gagne les eaux peu profondes au printemps pour frayer."),
  'amour-blanc': c(2, "Herbivore glouton : il peut manger chaque jour jusqu'à son propre poids en végétation aquatique, racines comprises. Près du bord, il sort souvent la queue de l'eau en se nourrissant ; il est décrit comme très nerveux."),

  // ── Eau de mer : poissons-clowns et demoiselles ──
  'poisson-clown-ocellaris': c(5, "Il vit en symbiose avec son anémone, qu'il évente et débarrasse de ses parasites. Le groupe est hiérarchisé : la femelle est la plus grande et dominante, puis le mâle, les autres restant non reproducteurs. Très territorial, plus agressif à la ponte ; le mâle courtise en mordillant, en poursuivant et en déployant ses nageoires, puis évente les œufs."),
  'poisson-clown-percula': c(5, "Il vit en association avec l'anémone, qu'il nettoie et nourrit en échange de sa protection. Chaque groupe compte un couple reproducteur et de zéro à quatre non-reproducteurs rangés par taille : la femelle est la plus grande. Les conflits opposent surtout les mâles, le plus petit finissant chassé de l'anémone."),
  'chirurgien-bleu': c(4, "Les juvéniles forment des bancs, et l'espèce se nourrit de zooplancton. Pour se défendre, il porte une lame de chaque côté du pédoncule caudal et des épines venimeuses sur les nageoires : à manipuler avec précaution."),
  'chirurgien-voile-jaune': c(3, "Grand nageur actif qui a besoin de beaucoup d'espace et broute les algues toute la journée. Légèrement territorial : il s'entend souvent mal avec les autres chirurgiens et malmène parfois des espèces paisibles ou ses congénères. En principe un seul chirurgien par bac."),
  'demoiselle-bleue': c(2, "Active le jour, elle patrouille une zone de roche et la défend fermement ; son agressivité augmente avec l'âge et vise surtout ses congénères et les poissons introduits après elle. Effrayée, elle fuit dans une anfractuosité. À introduire en dernier, avec beaucoup de cachettes."),
  'demoiselle-verte': c(3, "Dans la nature, elle forme de grands nuages au-dessus des Acropora et se disperse à l'approche d'un prédateur. En aquarium, les jeunes restent groupés quelques mois, puis l'agressivité envers les autres chromis apparaît vers 4 à 6 mois : le dominant repousse les autres et le groupe finit souvent à un ou deux survivants."),
  'labre-nettoyeur': c(5, "Il installe une station de nettoyage où il retire les parasites de poissons plus grands. Très actif, peu effarouché, il vit en couple à l'âge adulte ; les juvéniles sont territoriaux et nettoient seuls. Il lui faut de nombreux gros clients, sinon il peut en harceler un seul."),
  'poisson-ange-nain': c(3, "Timide, il se cache dans les petites anfractuosités, puis devient plus sociable quand son territoire est établi. Territorial et agressif envers ses congénères : les mâles peuvent se battre à mort, même si l'espèce vit en couple ou en harem. Mal nourri, il peut picorer les polypes de coraux."),
  'poisson-perroquet': c(3, "Il racle les algues sur le corail et la roche avec son bec et certaines espèces, plus grandes, mangent aussi du corail vivant. Avant de se reposer la nuit, plusieurs espèces s'enveloppent d'un cocon de mucus. La plupart naissent femelles puis deviennent mâles en changeant de couleur."),
  'gobie-crevette': c(5, "Il partage un terrier avec une crevette alpheidé. Chez le gobie Cryptocentrus étudié, la crevette ne sort qu'en présence du poisson, au contact de ses antennes et à ses ondulations de queue, et elle rentre avec lui face à un danger. Elle nettoie aussi le gobie."),
  'blennie-leopard': c(4, "Elle passe l'essentiel de son temps posée sur la roche, à racler presque en continu détritus et algues. En cas de menace, elle se glisse dans une fissure en laissant souvent dépasser la tête. Territoriale surtout envers les blennies de taille égale ou inférieure, elle tolère en général les demoiselles."),
  'poisson-lion-volant': c(4, "Surtout solitaire et nocturne, il chasse de la fin d'après-midi jusqu'à l'aube : il acculte ses proies avec ses grandes pectorales, puis les avale entières. Ses épines dorsales venimeuses ne servent qu'à la défense : il les tourne vers l'agresseur."),
  'hippocampe': c(5, "La femelle rejoint souvent le mâle tôt le matin pour une danse de salutation, queues enlacées, d'environ six minutes. Chez beaucoup d'espèces, le couple est durable. C'est le mâle qui porte la gestation dans sa poche, de 10 jours à six semaines, puis expulse les jeunes."),

  // ── Eau douce : cichlidés et grands poissons ──
  'cichlide-zebre-du-malawi': c(3, "Mbuna très agressif et territorial, peu adapté à un bac communautaire général. Il faut un mâle pour trois femelles, jamais plus d'un mâle dans moins de 200 litres. Le mâle dominant est plus coloré ; la femelle couve les œufs 3 à 4 semaines sans manger."),
  'cichlide-frontosa-tanganyika': c(3, "Poisson grégaire, à garder à cinq au moins, idéalement dix : les mâles n'ont pas de territoire mais forment une hiérarchie dominée par un ou plusieurs alphas, qui occupent chacun une cache. Il peut s'attaquer à des poissons nettement plus petits. La femelle incube les œufs 35 à 50 jours et nourrit même ses alevins."),
  'cichlide-paon-aulonocara': c(4, "Les mâles se disputent férocement en présence de femelles ; dans un grand bac avec roches et grottes, chacun peut défendre son territoire (un mâle pour trois ou quatre femelles). Le mâle danse près de la femelle, dans une dépression creusée sous un surplomb, puis elle couve les œufs environ 28 jours."),
  'oscar': c(4, "Peu agressif pour un cichlidé de sa taille, mais prédateur : à ne pas associer à des poissons nettement plus petits. Il apprend vite à mendier quand son propriétaire s'approche, creuse le substrat et abîme l'aquascape. Certaines populations chassent en faisant le mort."),
  'poisson-perroquet-nain-convict': c(3, "Idéalement gardé en couple dans un bac d'espèce : agressif et territorial, il peut s'attaquer à des poissons bien plus gros. À la ponte, la femelle nettoie le site et garde œufs puis alevins pendant que le mâle patrouille et repousse les intrus, parfois jusqu'à attaquer un doigt."),
  'gourami-geant': c(3, "Généralement pacifique avec les grands poissons, mais il mange les petits. Certains adultes deviennent très agressifs, souvent faute de place. Il développe une vraie personnalité et peut apprendre à reconnaître son propriétaire ; le mâle bâtit un grand nid de végétation."),
  'poisson-chat-requin-pangasius': c(2, "Il vit en banc, actif, avec une vue très mauvaise : un mouvement extérieur le fait fuir en se précipitant, au risque de se blesser. Il peut rester sur le flanc ou le dos pour récupérer. En bac domestique, le manque d'espace bloque sa croissance et peut écourter sa vie."),
  'tetra-rouge-du-congo': c(3, "Paisible mais très actif à la nage, ce qui peut effrayer des espèces timides. Craintif, surtout en petit nombre : à garder en banc mixte. Les mâles, plus grands et plus colorés, ont des nageoires étendues que les poissons mordilleurs abîment."),
  'tetra-glowlight': c(3, "Vif, paisible et grégaire : au moins six, de préférence dix ou plus, il se porte bien mieux avec ses congénères et paraît plus spectaculaire en groupe."),
  'tetra-a-queue-rouge': c(3, "Il forme des bancs très serrés, en nature comme en aquarium, à partir de six individus. Chez les tétras à nez rouge, la face pâlit quand ammoniac, nitrites ou nitrates montent et juste après un changement d'eau : une pâleur persistante signale un problème de paramètres."),
  'poisson-arlequin-cuivre': c(3, "Très paisible et grégaire : à garder à 8 ou 10 au moins, il est alors moins nerveux. À la ponte, il fixe ses œufs sous une large feuille au lieu de les disperser."),
  'poisson-clown-loche-yoyo': c(3, "Paisible et robuste, elle doit vivre en groupe de sa propre espèce. Comme la loche clown, elle a une hiérarchie avec querelles : les dominants malmènent parfois les plus faibles, d'où le besoin de cachettes. Excellente fouisseuse, elle apprécie un sable fin qui protège ses barbillons."),
  'xenotoca-poisson-a-queue-rouge': c(2, "Comportement imprévisible : certains individus s'intègrent bien, d'autres mordillent les nageoires, voire attaquent et tuent d'autres espèces. Particulièrement hostile aux poissons-chats, dont les Corydoras (nageoires et yeux abîmés) : un bac d'espèce est conseillé."),
  'molly-voile-de-lyre': c(3, "Surtout herbivore, il broute algues et végétaux. Les mâles, reconnaissables à leur grande dorsale en voile, peuvent être agressifs entre eux à la reproduction et poursuivre les femelles avec ardeur : deux femelles pour un mâle."),
  'endler': c(4, "Très actif et paisible. Les mâles ne se battent pas entre eux mais font constamment la cour aux femelles, nageoires déployées, en frétillant devant elles. Ce harcèlement peut être vigoureux : plusieurs femelles par mâle."),
  'bristlenose-ancistrus-nain': c(3, "Relativement pacifique, mais territorial envers ses congénères et les poissons de forme voisine. Il se reproduit dans une grotte et c'est le mâle qui s'occupe de la couvée."),
  'poisson-chat-synodontis': c(5, "Il nage souvent à l'envers, surtout près des objets ou du fond, et va plus vite ainsi. Sa coloration, claire sur le dos et sombre sur le ventre, le rend moins visible dans cette position et lui permet d'attraper des proies à la surface par en dessous. Surtout nocturne, paisible."),
  'poisson-chat-corydoras-venezuela': c(4, "Grégaire, il se déplace en banc de six au moins. Il vit surtout près du fond mais nage aussi dans tout le bac, très actif, et remonte respirer de l'air en surface quand il en a besoin. Naturellement paisible."),
  'poisson-roseau': c(3, "Nocturne, il respire aussi de l'air : privé d'air atmosphérique, il peut se noyer. Excellent évadé et sauteur, il exige un couvercle ajusté. Paisible et peu territorial, il mange tout poisson qui tient dans sa gueule et se fait dépasser au repas par les espèces très vives."),
  'anguille-serpent-mastacembelus': c(3, "Nocturne, elle chasse surtout la nuit, s'enfouit dans le substrat et déracine parfois les plantes. Prédateur à l'affût, elle avale les petits poissons entiers. Agressive envers sa propre famille et son espèce, pacifique avec des espèces de caractère comparable."),
  'perche-soleil-naine-decorative': c(2, "Généralement paisible mais territoriale : elle peut devenir agressive, surtout à la reproduction, et tolère mal ses congénères. À garder seule ou avec de petites espèces paisibles ; beaucoup de cachettes réduisent son agressivité. Elle préfère un courant doux."),

  // ── Eau de mer : papillons, anges, mandarins ──
  'poisson-papillon': c(3, "Pacifique, il ignore en général les autres poissons. Deux individus au motif proche se disputent souvent, sauf introduits en couple déjà formé. Il picore les surfaces rocheuses, timide et sensible au stress à l'arrivée. Il mange souvent mal les aliments préparés et peut refuser de manger longtemps ; en nature il se nourrit de polypes coralliens, d'anémones et de vers tubicoles, donc incompatible avec un récif."),
  'poisson-ange-royal': c(3, "Timide et discret, il préfère les récifs riches en cachettes et se faufile entre les crevasses ou reste sous les corniches. Son régime est presque exclusivement fait d'éponges et de tuniciers, broutés pendant la journée. Il vit seul ou en couple."),
  'cardinalis-de-banggai': c(4, "Il vit près des oursins, entre les épines desquels il se réfugie. Il forme des groupes stables d'environ neuf individus, peu mobiles, qui reviennent à leur place d'origine quand on les dérange. Le mâle incube les œufs dans sa bouche jusqu'à 30 jours sans se nourrir, et les jeunes y restent encore un temps."),
  'poisson-mandarin': c(4, "Plutôt solitaire et discret, il se nourrit de petits crustacés et d'autres invertébrés. Chaque soir, les femelles se regroupent pendant que les mâles tentent de les séduire ; quand une femelle choisit, le couple s'élève lentement au-dessus du récif et libère œufs et spermatozoïdes."),
  'gobie-nemateleotris': c(4, "Il reste immobile juste au-dessus de son terrier, face au courant, et capture le zooplancton qui passe. Paisible avec les autres espèces mais intolérant envers ses congénères : seul ou en couple. Il saute presque à coup sûr hors d'un bac non couvert."),
  'demoiselle-a-trois-bandes': c(3, "Elle vit en groupes d'environ 30 individus au-dessus de têtes d'Acropora et reste presque toute sa vie sur le même récif. Une hiérarchie de taille s'installe dès le jeune âge. Très territoriale, elle défend ses abris contre tout intrus et devient nettement plus agressive avec l'âge."),
  'requin-taupe-requin-de-recif-aquarium-geant': c(2, "Nocturne et peu actif, il a besoin d'un abri ombragé pour se cacher. Carnivore, il atteint plus d'un mètre et se reproduit par ponte d'œufs : un très grand bac est indispensable."),
  'gourami-dore': c(3, "Certains individus deviennent très agressifs en vieillissant, d'autres restent paisibles. Les mâles sont territoriaux, se disputent entre eux et deviennent très agressifs à la reproduction ; le mâle bâtit un nid de bulles parmi les plantes flottantes et veille dessus."),

  // ── Eau douce : compléments ──
  'apistogramma-viejita': c(4, "Le mâle établit un territoire, réagit agressivement aux autres mâles et tolère plusieurs femelles : structure de type harem. La femelle garde et soigne œufs et alevins, le mâle pouvant aider s'il vit en couple. Il lui faut des abris (végétation, racines, cavités)."),
  'hypancistrus-zebra-l046': c(3, "Territorial envers ses congénères et les espèces proches, il doit être le seul poisson de fond du bac, avec de nombreuses cachettes. Les mâles choisissent des cavités à l'entrée à peine plus grande qu'eux, qu'ils défendent en tentant d'y attirer les femelles."),
  'gambusie': c(2, "Très active et rapide, surtout en surface et à mi-hauteur, où un couvert flottant la rassure. Classée agressive : elle mordille souvent les nageoires des autres poissons. Vivipare, la femelle stocke le sperme et enchaîne les portées ; les mâles la poursuivent, d'où 1 mâle pour 2 à 3 femelles, en groupe de 3 au moins."),
  'pseudorasbora-goujon-asiatique': c(2, "Il mordille activement d'autres cyprinidés, carpes et tanches par exemple, en étang comme en aquarium, causant parfois des lésions profondes que les auteurs rapprochent de la prédation. Plutôt un poisson de mare qu'un poisson d'ornement."),
  'choquemort': c(3, "Il préfère former des bancs avec ses congénères plutôt qu'avec d'autres espèces. Hors de l'eau, il quitte les flaques et bondit de quelques centimètres sur la terre pour en rejoindre d'autres, en se guidant à la vue vers les reflets."),
  'poisson-meteo-raye': c(3, "Comme les autres loches Misgurnus, elle passe du temps entièrement enfouie dans le substrat, seuls les yeux dépassant, et avale de l'air en surface dans une eau pauvre en oxygène. Pacifique, plus à l'aise avec des congénères, elle saute souvent hors du bac. Sa sensibilité à la pression atmosphérique est supposée, pas démontrée."),
  'perche-soleil': c(3, "Le mâle bâtit son nid dans les baies végétalisées, souvent en colonies de 3 à 15 nids, et le défend avec agressivité : opercules écartés, charges, morsures, combats bouche contre bouche. Il ventile le nid et protège les alevins environ 10 jours, jusqu'à les ramener dans sa bouche."),
  'goujon-de-l-amour': c(2, "Prédateur de poissons, d'œufs de poissons et de chironomes. Il atteint de très fortes densités dans les bras morts des cours d'eau. Espèce invasive : non adaptée à l'aquarium d'ornement."),
  'poisson-chat-noir-americain': c(2, "Actif la nuit, il se nourrit au fond de matières végétales et animales. Après la ponte, un des parents reste avec les œufs et les évente, puis veille sur les alevins jusqu'à environ 2,5 cm."),
  'poisson-tete-de-serpent-du-nord': c(3, "Il remonte respirer en surface, ce qui lui permet de vivre en eau pauvre en oxygène, et peut franchir de petites étendues de terre en ondulant. Les deux parents construisent et gardent le nid jusqu'à environ quatre semaines après l'éclosion. Très agressif envers ses proies, il chasse souvent en bancs."),
  'gambusie-2': c(2, "Très active et rapide, surtout en surface et à mi-hauteur, où un couvert flottant la rassure. Classée agressive : elle mordille souvent les nageoires des autres poissons. Vivipare, la femelle stocke le sperme et enchaîne les portées ; les mâles la poursuivent, d'où 1 mâle pour 2 à 3 femelles, en groupe de 3 au moins."),

  // ── Eau de mer : poissons-clowns suite ──
  'poisson-clown-tomate': c(4, "Il vit en symbiose avec une anémone qui le protège, et défend son hôte. Hiérarchie de dominance stricte : la femelle, la plus grande et la plus agressive, domine, et seul un couple se reproduit. Adulte, il est réputé agressif et territorial, même envers d'autres poissons-clowns : à garder seul ou en couple."),
  'poisson-clown-de-clark': c(4, "Il vit en symbiose avec au moins 10 espèces d'anémones, dont il s'éloigne peu. Agressif envers les autres espèces, surtout pour défendre son anémone ; une hiérarchie de dominance règne : les juvéniles qui arrivent subissent les agressions les plus violentes et peuvent être chassés. Le mâle prépare le nid et s'occupe l'essentiel des œufs."),
  'poisson-clown-skunk': c(4, "Paisible, il s'accorde mieux avec des poissons calmes qu'avec des espèces agitées ou agressives. Il forme des couples monogames et le plus grand juvénile d'une paire devient la femelle. Une anémone n'est pas obligatoire mais il s'installe mieux avec ; mieux vaut un individu seul ou une paire, car d'autres adultes provoquent des conflits."),
  'poisson-clown-a-dos-rouge': c(4, "Il vit en symbiose avec les anémones, surtout Entacmaea quadricolor. Hiérarchie stricte fondée sur la taille : la femelle est la plus grande, puis le mâle reproducteur, puis les mâles non reproducteurs ; si la femelle meurt, le mâle devient femelle. En aquarium, il peut devenir territorial et agressif une fois installé."),
  'poisson-clown-marron': c(3, "L'un des poissons-clowns les plus agressifs : à introduire en dernier pour qu'il ne harcèle pas les poissons ajoutés après lui, et pas en plusieurs exemplaires sauf couple déjà formé. Il aime avoir un hôte, sans garantie qu'il s'y installe. Diurne."),
  'demoiselle-azur': c(3, "Semi-agressive, mais l'une des plus faciles de son genre. Les adultes défendent leur territoire, avec plus de conflits à maturité ou quand l'espace et les cachettes manquent. Dans la nature, elle forme de petits regroupements près des coraux branchus ; plusieurs individus s'introduisent ensemble."),
  'demoiselle-a-trois-points': c(2, "Elle devient nettement plus querelleuse en vieillissant : très territoriale et mordeuse, elle harcèle souvent les autres poissons, ses congénères en premier. Les juvéniles sont bien moins agressifs et peuvent s'associer à un corail ou une anémone, comme un poisson-clown."),
  'demoiselle-jaune-et-bleue': c(3, "Semi-agressive mais l'une des demoiselles les moins agressives. Elle peut défendre un abri favori et mordiller des poissons de taille similaire. Dans la nature, elle forme de petits groupes autour des Acropora ; en grand bac, des groupes sont possibles si les poissons sont introduits ensemble."),
  'pseudochromis-de-fridman': c(3, "Territorial et parfois agressif envers d'autres poissons, tout en restant plutôt timide. Il lui faut de nombreuses cachettes (fissures, grottes) et il vaut mieux le placer avec des poissons plus grands, peu susceptibles d'être harcelés."),
  'pseudochromis-royal': c(2, "Très territorial et agressif, il peut intimider des poissons bien plus grands. Il défend farouchement ses cavités dans la roche, mordille les nageoires de compagnons beaucoup plus gros et peut se battre à mort avec ses congénères. Il ne convient à un nano que seul."),
  'gramma-royal': c(4, "Territorial, il délimite son domaine parmi les rochers et chasse les petits poissons intrus, gueule grande ouverte. Il nage souvent à la verticale, voire à l'envers, sous les corniches : ce n'est pas un signe de maladie. Le mâle bâtit un nid d'algues et le garde un mois ou plus ; pas de congénères sauf en couple."),
  'assessor-bleu': c(4, "Il forme des bancs pouvant compter jusqu'à 100 individus et se réfugie dans les grottes, crevasses et sous les corniches. Il nage souvent à l'envers. Le mâle incube les œufs dans sa bouche 15 à 16 jours."),
  'blennie-bicolore': c(3, "Pacifique mais territoriale, avec plus d'agressivité dans les petits bacs. Elle va de perchoir en perchoir, surveille l'aquarium depuis une corniche et broute en permanence algues et biofilm. Une seule par bac : conflits signalés avec d'autres blennies et gobies."),
  'blennie-a-queue-fourchue': c(4, "Elle nage souvent en pleine eau, au-dessus des roches, plus sûre d'elle que la plupart des blennies. Deux crocs venimeux dans la mâchoire inférieure, utilisés en dernier recours ; morsure peu dangereuse mais douloureuse. Adultes solitaires ou en couple, un peu territoriaux, sauteurs experts."),
  'gobie-clown': c(4, "Il se perche sur les branches externes des Acropora, souvent en groupes de 5 à 15. Sa défense est un mucus cutané amer et toxique. Peu agressif, il défend pourtant son territoire face à ses congénères : seul ou en couple, avec changement de sexe dans la paire, le mâle gardant les œufs."),
  'gobie-neon': c(4, "Il tient une station de nettoyage. Chez les gobies néon (Elacatinus), les clients se rassemblent, le client déclenche l'interaction et le nettoyeur y met fin ; la station protège le nettoyeur des gros prédateurs. Service comparable à celui des labres nettoyeurs."),
  'gobie-nettoyeur-de-sable': c(4, "Il se nourrit en tamisant du sable pour y trouver de petits invertébrés benthiques. Les couples sont monogames et restent en vol stationnaire près du terrier qu'ils construisent ; le mâle garde les œufs pondus dans le terrier."),
  'gobie-sifteur-de-sable': c(3, "Il avale des bouchées de sable puis filtre algues, invertébrés et matières organiques. Peu d'éléments de comportement social sont documentés pour cette espèce."),
  'gobie-a-longs-filaments': c(5, "Il partage un terrier avec une crevette pistolet. Grâce à sa meilleure vue, il fait office de vigie : au danger, il agite la queue pour avertir la crevette, qui garde le contact par une antenne posée sur sa queue. Dans la nature, un couple partage le même terrier ; relation de mutualisme."),
  'anthias-a-ecailles-carrees': c(4, "Il forme de grands bancs au-dessus des massifs coralliens, se nourrissant de zooplancton en pleine eau. Le mâle, très territorial, domine un harem de femelles et de juvéniles ; si les mâles disparaissent, une femelle change de sexe en 2 à 4 semaines."),
  'cardinal-pyjama': c(3, "Il vit en petits groupes à hiérarchie stricte, sans recourir à l'agressivité pour dominer. Il se reproduit toute l'année, surtout la nuit ; le mâle incube les œufs dans sa bouche 8 à 31 jours."),
  'poisson-ange-bicolore': c(3, "Territorial : une fois installé, il défend une zone parmi les roches, plus audacieux que la plupart de son genre, et son agressivité augmente avec le temps. Seul ou en couple, il broute presque toute la journée et picore LPS, coraux mous, zoanthides et manteaux de bénitiers."),
  'poisson-ange-citron': c(3, "Actif et territorial, il s'approprie une portion de récif. Agressif surtout envers les autres poissons-anges de forme proche : seul de préférence. Les juvéniles restent discrets près des coraux et crevasses. Il picore LPS, zoanthides, coraux mous, bénitiers et anémones."),
  'poisson-ange-cherub': c(3, "Discret au début, il reste caché dans les grottes du rocher vivant, puis devient un brouteur actif et audacieux. En aquarium, il est très territorial : un seul mâle par système, combats sévères entre mâles. Semi-agressif, à associer à des compagnons robustes."),
  'poisson-ange-de-bellus': c(4, "Il vit en petits harems d'un mâle et jusqu'à six femelles ; si le mâle disparaît, la femelle dominante change de sexe et de couleur en 2 à 3 semaines. Il forme des bancs en pleine eau pour se nourrir de zooplancton. Dimorphisme marqué : mâles gris pâle à bandes dorées, femelles à large bande noire."),
  'chirurgien-pourpre': c(3, "Semi-agressif, il défend farouchement nourriture, abri et lieu de sommeil. Particulièrement agressif envers les autres chirurgiens, surtout les Zebrasoma : un seul de son genre par bac. Nageur actif qui patrouille l'eau libre et broute presque sans arrêt."),
  'chirurgien-voile': c(4, "Très énergique, il a besoin d'un long espace horizontal pour nager et faire demi-tour. Ses nageoires dorsale et anale en voile sont impressionnantes déployées. Audacieux, peu belliqueux envers les autres espèces mais agressif envers ses congénères ; il broute de roche en roche et peut grignoter des polypes."),
  'chirurgien-kole': c(3, "Il broute en permanence détritus et microalgues. Semi-agressif : généralement paisible, mais en conflit avec ceux qui lui ressemblent ; les autres tangs sont ses principaux rivaux, un seul par bac. Il lui faut un bac mature."),
  'chirurgien-bleu-poudre': c(3, "Nageur infatigable qui patrouille de longues distances : bac long indispensable. En captivité, il défend ses zones de broutage et supporte mal congénères et poissons de forme proche, avec une agressivité forte envers les poissons-papillons. Trop à l'étroit, il se stresse et devient agressif."),
  'nason-a-licorne': c(3, "Très énergique et presque toujours en mouvement, il demande un grand espace de nage. Généralement pacifique, il peut se chamailler avec les espèces proches, et deux congénères ne doivent pas être gardés ensemble ; ses épines caudales tranchantes rendent tout affrontement dangereux. Herbivore."),
  'labre-fee-de-scott': c(4, "En parade, le mâle remonte du fond et déploie toutes ses nageoires, aux couleurs plus intenses. Dans la nature, les groupes sont dominés par des femelles et des juvéniles ; en bac, un seul mâle, car il peut devenir territorial envers les autres labres fées. Sauteur : couvercle ajusté. Timide à l'arrivée."),
  'labre-de-carpenter': c(4, "Pendant la parade, le mâle effectue de courts et rapides élans dans la colonne d'eau, nageoires déployées et couleurs intensifiées en présence de femelles. Il part d'un point d'appui près des roches ou du sable et y revient. Cette parade est bien moins fréquente sans femelles."),
  'labre-a-six-lignes': c(2, "Il passe la journée à patrouiller dans les roches et à se faufiler dans les cavités. Installé, il devient souvent agressif et territorial, surtout envers les autres labres, les poissons de forme proche, les espèces timides et les nouveaux arrivants : à ajouter en dernier, un seul par bac. Il chasse aussi de petits vers."),
  'labre-jaune': c(3, "Fourrageur très actif qui patrouille rochers, sable et débris, puis s'enfouit dans le substrat pour dormir ou quand il est effrayé. Tempérament doux envers ses congénères, il cohabite avec d'autres labres calmes ; dans la nature, il est souvent en petits groupes."),
  'labre-leopard': c(4, "Il passe la journée à fouiller le sable et les débris à la recherche de micro-proies, d'une nage ondulante, et s'enfouit dans le sable au crépuscule. En nature, il vit en couples ou en petits groupes de femelles formant un harem, une femelle devenant mâle. Pacifique et craintif, fragile : bac mature et sable épais."),
  'mandarin-psychedelique': c(4, "Il vit près du fond et se déplace par petits bonds grâce à ses pectorales. Il broute en permanence le substrat à la recherche de copépodes et autres micro-organismes vivants. À la parade, mâle et femelle remontent dans la colonne d'eau dans l'obscurité, ventre contre ventre. Les mâles sont très territoriaux entre eux."),
  'poisson-comete': c(4, "Réservé et timide, nocturne, il passe la journée caché dans les grottes et crevasses. Menacé, il déploie ses nageoires impaires et s'enfonce tête première dans une crevasse en laissant l'arrière dépasser, ce qui imite la tête d'une murène."),
  'poisson-cocher': c(3, "Sociable, il vit souvent en couple ou en petits groupes, en suspension au-dessus des pentes récifales. Il se nourrit de jour, surtout de petits invertébrés benthiques, au tempérament généralement paisible. Les juvéniles peuvent parfois nettoyer de plus gros poissons."),
  'baliste-picasso': c(3, "Il peut être agressif, certains individus plus que d'autres, mais bien moins meurtrier que d'autres balistes. Il remanie le décor et grignote les objets : roches bien fixées. Il mord et mange de nombreux invertébrés, donc déconseillé en récif."),
  'baliste-clown': c(3, "Agressif et territorial : adulte, c'est un solitaire qui chasse les intrus, son caractère s'affirmant vers 20 cm. Il remanie sans cesse roches et substrat, mord chauffages et équipements, et s'intéresse aux mains qui entrent dans l'eau. Il atteint 25 à 38 cm en captivité."),
  'baliste-noir-a-dents-rouges': c(3, "Les adultes forment couramment de grands bancs, les juvéniles vivent seuls près des crevasses. Les mâles sont très territoriaux. Apeuré, il se réfugie dans un trou favori et bloque sa première épine dorsale en position verticale. Il se nourrit de zooplancton et d'éponges."),
  'poisson-coffre-jaune': c(3, "Il nage lentement avec ses petites nageoires, souvent en suspension, et peine dans les forts courants. Fortement stressé ou blessé, il libère une ostracitoxine capable de tuer ses voisins d'aquarium. Craintif à l'introduction, semi-agressif envers ses congénères : seul, sauf paire déjà formée."),
  'canthigaster-de-valentin': c(3, "Protégé par la tétrodotoxine de sa peau, il est imité par un poisson non toxique (mimétisme batésien). Omnivore, il broute surtout algues filamenteuses et tuniciers. Il vit en harems dominés par un mâle territorial, chaque femelle occupant son propre domaine."),
  'poisson-rasoir': c(5, "Il nage à la verticale, la tête vers le bas, souvent en banc. Dérangé, il file entre les branches de coraux ou les épines d'oursins Diadema."),
  'hippocampe-kuda': c(5, "Il nage à la verticale et s'accroche par la queue. Comme chez beaucoup d'hippocampes, la femelle rejoint souvent le mâle tôt le matin pour une danse de salutation, et c'est le mâle qui porte la gestation."),
  'poisson-pipe-a-bandes': c(3, "Il vit dans les récifs et lagons protégés, généralement dans des cavités et des fissures. Les mâles portent les œufs sous leur face inférieure."),
  'opistognathe-a-front-jaune': c(5, "Il creuse un terrier dans le sable avec sa bouche et, le jour, se tient à la verticale au-dessus du trou, s'y réfugiant queue la première à l'alerte ; la nuit, il bouche l'entrée avec une coquille ou un débris. Le mâle couve les œufs dans sa bouche environ une semaine, sans se nourrir."),
  'poisson-lapin-renard': c(3, "Il broute surtout des algues vertes et les algues indésirables du bac. Généralement indifférent aux autres poissons, que ses épines venimeuses tiennent à distance, mais deux individus de l'espèce se disputent : un seul par bac. Stressé, il prend rapidement une coloration marbrée."),
  'idole-des-maures': c(3, "Souvent observée en couple, elle forme parfois des regroupements. Elle se nourrit surtout d'éponges encroûtantes, mais aussi de polypes de coraux, de tuniciers et d'autres invertébrés benthiques : un régime très difficile à reproduire en aquarium."),
  'anguille-ruban': c(4, "Les plongeurs la voient souvent la tête et l'avant du corps hors des fissures de son terrier. Active le jour, elle change de couleur avec l'âge : juvéniles presque noirs, mâles adultes bleus à face jaune, femelles jaunes. En aquarium domestique, beaucoup cessent de manger et vivent rarement plus d'un an."),
  'napoleon': c(4, "Solitaire, souvent vu sur les pentes récifales abruptes, il est réputé intelligent et curieux et s'approche des plongeurs. Prédateur opportuniste, il broie les proies à coquille dure ; actif le jour, il se retire la nuit dans des grottes. Il peut vivre jusqu'à 30 ans et atteint une taille énorme."),
  'poisson-pierre-marin': c(3, "Parfaitement camouflé, il reste immobile, partiellement enfoui dans le sable avec ses pectorales, et aspire d'un coup la proie qui passe : chasseur à l'affût. Ses 12 à 14 épines dorsales à poche de venin ne servent qu'à la défense, mais son venin est extrêmement toxique."),
  'balibot-raye': c(3, "Les juvéniles forment des bancs denses en boule d'environ 100 poissons ; les adultes vivent seuls ou en petits groupes d'une vingtaine, cachés le jour sous des rebords rocheux. Ils fouillent le sable à la recherche de crustacés, mollusques et vers. Épines venimeuses sur la première dorsale et les pectorales."),

  // ── Bassin : variétés de poissons rouges ──
  'poisson-rouge-bubble-eye': c(2, "Nageur peu puissant, il lui arrive d'avoir la tête basse et oscillante. Ses deux grandes poches sous les yeux se balancent à la nage et peuvent être aspirées par les filtres ; fragiles, elles risquent l'infection si elles éclatent. Sa vue réduite le désavantage face aux poissons plus rapides."),
  'shubunkin': c(4, "Actif et joueur, il est sociable et se porte mieux en groupe, avec au moins deux congénères. Assez rustique, il passe l'hiver dehors dans la plupart des bassins ; sa nage athlétique complique un peu les attaques de gros poissons."),
  'ryukin': c(3, "Il se garde en groupe avec d'autres poissons rouges fancy ; mieux vaut éviter le poisson rouge commun, plus rapide, qui le devance au repas. Gros mangeur, il remue sans cesse le substrat."),
  'scalaire-manacapuru': c(4, "Généralement paisible, mais il peut se disputer avec ses congénères : petit groupe en partant de six juvéniles pour qu'un couple se forme. Les mâles sont plus agressifs et territoriaux à la reproduction. Le couple pond sur une surface verticale (feuille, ardoise) et garde œufs et alevins, qu'il peut manger s'il est mal nourri."),
  'tetra-buenos-aires-albinos': c(3, "Grégaire, il se sent en sécurité à partir de six individus et occupe surtout la surface et la zone médiane. Classé pacifique, il peut toutefois mordiller les nageoires des congénères lents ou à longues nageoires, risque qui diminue en banc de huit ou plus. Il saute facilement : couvercle ajusté."),
  'blue-gourami': c(3, "Certains individus deviennent très agressifs en vieillissant, d'autres restent paisibles. Les mâles sont territoriaux, se disputent entre eux et deviennent très agressifs à la reproduction ; le mâle bâtit un nid de bulles parmi les plantes flottantes et veille dessus."),
};

export function comportementEspece(slug: string): Comportement | null {
  return COMPORTEMENTS[slug] ?? null;
}

// Premier niveau « très agréable à observer » : seuil utilisé pour mettre en avant
// une fiche (lien vers la page des poissons à observer).
export const NIVEAU_VEDETTE = 4;
